<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller { public function showLogin(){return view('auth.login');} public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required']); if(Auth::attempt($data,$r->boolean('remember'))){$r->session()->regenerate();return redirect()->intended(route('account'))->with('success','Welcome back.');}return back()->withErrors(['email'=>'The credentials do not match our records.'])->onlyInput('email');} public function showRegister(){return view('auth.register');} public function register(Request $r){$data=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users','phone'=>'nullable|string|max:30','password'=>'required|min:8|confirmed']);$u=User::create($data);Auth::login($u);return redirect()->route('account')->with('success','Welcome to Emerald Hair.');} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('home');} }
